head.script:
scwin.onpageload = function() {
    // 페이지리스트 세팅
	pageList1.setCount(100);
};

// 샘플팝업
scwin.popOpen_onclick = function (e) {
    var options = {
        id : "exam_popup",
        type : "wframePopup",
        width: "700px",
        height: "530px",
        top: "10px",
        left: "10px",
        popupName : "샘플팝업",
        modal : true
    }; 
    $c.win.openPopup("/pub/sample_popup.xml", options);
};

// 샘플팝업 (윈도우)
scwin.winpopOpen_onclick = function (e) {
    var options = {
        id : "exam_winpopup",
        type : "browserPopup",
        width: "700px",
        height: "480px",
        top: "10px",
        left: "10px",
        popupName : "샘플팝업 (윈도우)",
        modal : true
    }; 
    $c.win.openPopup("/pub/sample_popup.xml", options);
};
